import * as zlib from "node:zlib";
import { Buffer } from "node:buffer";
import * as Astronomy from "npm:astronomy-engine@2.1.19";
import { createClient } from "npm:@supabase/supabase-js@2";
import { handleHabitsRequest } from "./habits.ts";
import { HLS_JS } from "./hls-asset.ts";
import { handleTvCatalog, tvCatalogResponse } from "./tv-catalog.ts";
import { tvRelayResponse, tvHealthResponse } from "./tv-relay.ts";
import { timeMachineApi, timeMachinePage } from "./time-machine.ts";
import { samacharApi, samacharPage } from "./samachar.ts";
import { fmApi, fmPage } from "./fm.ts";
import { explorePage } from "./explore.ts";
import { FOUNDATION_JS, FOUNDATION_CSS, flagsResponse, readFlags } from "./foundation.ts";
import { HOME_JS, HOME_CSS } from "./home-enhance.ts";
import { BUNDLE_PAGES, bundlePage, bundleApi as bundleRuntimeApi } from "./bundle-runtime.ts";
import { RASHIFAL_PAGES, rashifalPage, rashifalApi, injectRashifalLauncher } from "./rashifal.ts";
import { JYOTISH_CHAT_CSS, JYOTISH_CHAT_HTML, JYOTISH_CHAT_JS } from "./jyotish-chat-ui.ts";
import { TRUST_PATHS, LAUNCH_JS, launchPage, launchNotFound, polishLegacyHtml } from "./launch-polish.ts";
import { toolsResponse } from "./tool-pages.ts";
import { dedicatedPage } from "./dedicated-pages.ts";
import { rashifalSsr } from "./rashifal-ssr.ts";
import { sharedChrome } from "./shared-shell.ts";
const CSS=":root{--g:#176f3b;--g2:#e8f5ec;--bg:#f5f8f5;--ink:#132218;--muted:#68756c;--line:#dfe7e1;--red:#c52e2e;--gold:#9b6a08;--purple:#6b5a8f}*{box-sizing:border-box}body{margin:0;font-family:Inter,"Noto Sans Devanagari",system-ui,sans-serif;background:linear-gradient(#f9fbf9,#f3f7f4);color:var(--ink)}button,input,select{font:inherit}.wrap{width:min(1200px,calc(100% - 28px));margin:auto}.top{position:sticky;top:0;z-index:20;background:rgba(255,255,255,.94);border-bottom:1px solid var(--line);backdrop-filter:blur(14px)}.nav{height:66px;display:flex;align-items:center;justify-content:space-between;gap:12px}.brand{font-weight:950;font-size:20px;display:flex;align-items:center;gap:9px}.mark{width:38px;height:38px;border-radius:12px;background:var(--g);display:grid;place-items:center;color:#fff}.badge{font-size:10px;background:var(--g2);color:var(--g);padding:5px 7px;border-radius:99px}.tabs{display:flex;gap:6px;flex-wrap:wrap}.tabs button{border:1px solid var(--line);background:#fff;border-radius:10px;padding:8px 10px;cursor:pointer}.tabs button.active{background:var(--g);color:#fff;border-color:var(--g)}main{padding:22px 0 70px}.hero{background:linear-gradient(135deg,#0b5d2d,#248a4c);color:#fff;border-radius:26px;padding:24px;display:grid;grid-template-columns:1.25fr .75fr;gap:18px;box-shadow:0 22px 55px rgba(16,88,45,.16)}.hero h1{font-size:clamp(36px,5vw,68px);margin:5px 0}.hero small{opacity:.82}.hero-side{display:grid;gap:10px}.glass{background:rgba(255,255,255,.12);border:1px solid rgba(255,255,255,.2);border-radius:15px;padding:13px}.glass strong{display:block;font-size:18px;margin-top:4px}.grid{display:grid;grid-template-columns:1.55fr .65fr;gap:16px;margin-top:16px}.card{background:#fff;border:1px solid var(--line);border-radius:20px;padding:18px;box-shadow:0 10px 28px rgba(20,48,30,.055)}.card h2,.card h3{margin:0 0 10px}.muted{color:var(--muted);font-size:12px}.filters{display:grid;grid-template-columns:1fr 1fr .7fr auto;gap:8px;margin-bottom:12px}select,input{width:100%;border:1px solid var(--line);border-radius:11px;padding:10px 11px;background:#fff}.go{background:var(--g);color:#fff;border:0;border-radius:11px;padding:10px 14px;font-weight:800;cursor:pointer}.week,.days{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:6px}.week div{text-align:center;font-size:11px;font-weight:800;color:var(--muted);padding:5px}.day{min-height:112px;border:1px solid #e8efea;background:#fbfdfb;border-radius:13px;padding:9px;cursor:pointer;position:relative;text-align:left}.day:hover{border-color:#8fc39e}.day.sat .n{color:var(--red)}.day.today{outline:2px solid #63b179;background:#edf9f0}.n{font-size:20px;font-weight:950}.ad{font-size:9px;color:var(--muted);float:right}.tithi{font-size:10px;color:var(--purple);font-weight:800;margin-top:7px}.event{font-size:9px;color:var(--gold);font-weight:800;margin-top:5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.ns{font-size:9px;color:var(--muted);margin-top:5px}.side-stack{display:grid;gap:16px}.kv{display:grid;grid-template-columns:1fr 1fr;gap:8px}.kv div{background:#f7faf8;border-radius:12px;padding:10px}.kv span{display:block;font-size:10px;color:var(--muted)}.kv strong{font-size:14px}.detail{margin-top:16px}.detail-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.metric{background:#f7faf8;border:1px solid #e7ede8;border-radius:12px;padding:11px}.metric span{display:block;font-size:10px;color:var(--muted)}.notice{background:#f8fbf8;border:1px dashed #bed7c5;border-radius:12px;padding:11px;font-size:12px}.safe{display:flex;gap:8px;align-items:center;color:#d9ffe5;font-size:12px;font-weight:800}.section{display:none}.section.active{display:block}.form{display:grid;grid-template-columns:1fr 1fr;gap:10px}.form .full{grid-column:1/-1}.astro-out{margin-top:15px}.planet-table{width:100%;border-collapse:collapse}.planet-table th,.planet-table td{font-size:12px;padding:7px;border-bottom:1px solid var(--line);text-align:left}.timeline{display:grid;gap:10px}.eventrow{display:grid;grid-template-columns:80px 1fr;gap:12px;border:1px solid var(--line);border-radius:14px;padding:12px}.eventrow time{font-size:22px;font-weight:950;color:var(--g)}.footer{margin-top:18px;text-align:center;color:var(--muted);font-size:11px}@media(max-width:800px){.hero,.grid{grid-template-columns:1fr}.filters{grid-template-columns:1fr 1fr}.detail-grid{grid-template-columns:1fr 1fr}.form{grid-template-columns:1fr}.form .full{grid-column:1}}@media(max-width:560px){.wrap{width:min(100% - 18px,1200px)}.days,.week{gap:3px}.day{min-height:90px;padding:6px}.tithi{font-size:9px}.ns{display:none}.hero{padding:18px}.tabs{gap:4px}.tabs button{font-size:11px;padding:7px 8px}}.note-prev{margin-top:5px;font-size:9px;color:#176f3b;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.note-box{margin-top:14px;border-top:1px solid var(--line);padding-top:13px}.note-box textarea{width:100%;min-height:90px;margin-top:8px;border:1px solid var(--line);border-radius:12px;padding:10px;resize:vertical}.note-actions{display:flex;gap:10px;align-items:center;margin-top:8px}.auth-card{border-color:#cfe8d7;background:linear-gradient(180deg,#fff,#f8fcf9)}.auth-form{display:grid;gap:8px}.auth-divider{display:flex;align-items:center;gap:8px;margin:9px 0;color:var(--muted);font-size:10px}.auth-divider:before,.auth-divider:after{content:'';height:1px;background:var(--line);flex:1}.google-auth{width:100%;border:1px solid #d8dde5;background:#fff;color:#202124;border-radius:10px;padding:9px 11px;font-weight:800;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:8px}.google-auth:hover{background:#f8fafd;border-color:#b9c1ce}.google-auth:disabled{opacity:.55;cursor:not-allowed}.otp-wrap{display:none;grid-template-columns:1fr auto;gap:8px}.auth-buttons{display:flex;gap:7px;flex-wrap:wrap}.ghost{border:1px solid var(--line);background:#fff;border-radius:10px;padding:8px 10px;cursor:pointer;font-weight:700}
.otd-hero{background:linear-gradient(135deg,#102b1b,#176f3b 65%,#268a4d);color:#fff;border-radius:24px;padding:22px;display:flex;justify-content:space-between;gap:18px;align-items:end;box-shadow:0 18px 44px rgba(23,111,59,.16)}
.otd-hero h2{font-size:32px;margin:5px 0}.otd-hero p{margin:0;opacity:.86;max-width:760px}.otd-privacy{background:rgba(255,255,255,.12);border:1px solid rgba(255,255,255,.2);padding:10px 12px;border-radius:12px;font-size:12px;font-weight:800;white-space:nowrap}
.otd-controls{margin-top:14px}.otd-nav{display:grid;grid-template-columns:auto minmax(130px,180px) auto auto;gap:8px;align-items:center}.otd-stats{display:grid;grid-template-columns:repeat(5,1fr);gap:8px;margin-top:12px}.otd-stats>div{background:#f5faf6;border:1px solid #e0ece3;border-radius:13px;padding:10px}.otd-stats span{display:block;color:var(--muted);font-size:10px}.otd-stats strong{font-size:20px;color:var(--g)}
.otd-toolbar{display:flex;gap:10px;align-items:center;justify-content:space-between;margin-top:12px;flex-wrap:wrap}.otd-types{display:flex;gap:6px;flex-wrap:wrap}.otd-types button{border:1px solid var(--line);background:#fff;border-radius:999px;padding:7px 10px;cursor:pointer}.otd-types button.active{background:var(--g);border-color:var(--g);color:#fff}.otd-toolbar select{width:auto;min-width:180px}
.otd-timeline{margin-top:14px}.otd-event{display:grid;grid-template-columns:92px 1fr;gap:14px;background:#fff;border:1px solid var(--line);border-radius:16px;padding:14px;box-shadow:0 8px 24px rgba(20,48,30,.045)}.otd-event.is-highlight{border-color:#d9bc72;background:linear-gradient(180deg,#fffdf7,#fff)}.otd-year{font-size:25px;font-weight:950;color:var(--g);letter-spacing:-.04em}.otd-meta{display:flex;gap:6px;align-items:center;flex-wrap:wrap;margin-bottom:6px}.otd-type,.otd-chip,.otd-verify,.otd-highlight{font-size:9px;padding:4px 7px;border-radius:999px}.otd-type.event{background:#e8f5ec;color:#176f3b}.otd-type.birth{background:#edf2ff;color:#38569a}.otd-type.death{background:#f2eff5;color:#6e5c7d}.otd-chip{background:#f3f5f3;color:#59645c}.otd-verify.ok{background:#e8f5ec;color:#176f3b}.otd-verify.review{background:#fff1e8;color:#9b4c17}.otd-highlight{background:#fff5d8;color:#8a6100;font-weight:800}.otd-body h3{font-size:16px;margin:0 0 6px}.otd-body p{margin:0 0 8px;color:#435047;line-height:1.55;font-size:13px}.otd-foot{display:flex;gap:10px;align-items:center;justify-content:space-between;color:var(--muted);font-size:10px}.otd-source{color:var(--g);font-weight:800}
@media(max-width:700px){.otd-hero{align-items:flex-start;flex-direction:column}.otd-hero h2{font-size:26px}.otd-nav{grid-template-columns:1fr 1fr}.otd-nav input{grid-column:1/-1;grid-row:1}.otd-stats{grid-template-columns:repeat(2,1fr)}.otd-event{grid-template-columns:64px 1fr}.otd-year{font-size:19px}.otd-toolbar select{width:100%}}

.grid{align-items:start}
.side-stack{align-self:start;align-content:start;grid-auto-rows:max-content}
.day{min-height:94px}
.ns{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.home-otd-card{overflow:hidden}
.home-major{border:1px solid #e7dec7;background:#fffaf0;border-radius:14px;padding:13px;margin:10px 0 12px}
.home-major-year{font-size:24px;font-weight:950;color:#8b4b16}
.home-major-title{font-weight:850;line-height:1.45;margin:4px 0 6px}
.home-major-meta{display:flex;gap:6px;flex-wrap:wrap;align-items:center}
.home-major-meta span{font-size:9px;padding:4px 7px;border-radius:999px;background:#f2eee3;color:#6c5d45}
.home-major-meta .ok{background:#e8f5ec;color:#176f3b}
.home-major-meta .review{background:#fff0e8;color:#9b4c17}
#homeOtdMajor{transition:opacity .22s ease,transform .22s ease;min-height:150px}
#homeOtdMajor.home-otd-swap{opacity:.12;transform:translateY(4px)}
.home-major-count{margin-left:auto;background:#eef6ef!important;color:#176f3b!important;font-variant-numeric:tabular-nums}
@media(prefers-reduced-motion:reduce){#homeOtdMajor{transition:none!important}#homeOtdMajor.home-otd-swap{opacity:1;transform:none}}
.footer{padding:18px 0 6px;line-height:1.6}
.footer a{color:var(--g);font-weight:800;text-decoration:none}
.china-intro{max-width:850px;line-height:1.65}
.astro-form-card{background:linear-gradient(180deg,#fffdf8,#fff);border-color:#eadfc7}
.astro-form-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.astro-form-grid .full{grid-column:1/-1}
.astro-check{display:flex;gap:8px;align-items:center;border:1px solid var(--line);border-radius:11px;padding:10px 11px;background:#fff}
.astro-advanced{grid-column:1/-1;border:1px dashed #d9ccb0;border-radius:12px;padding:10px;background:#fffdf8}
.astro-advanced summary{cursor:pointer;font-weight:800;color:#72511c}
.astro-advanced-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:10px}
.china-sheet{margin-top:16px;background:#fffaf0;border:2px solid #a75b38;border-radius:18px;padding:20px;box-shadow:0 14px 36px rgba(92,55,26,.08)}
.china-om{text-align:center;color:#9b3e23;font-weight:900;font-size:13px;letter-spacing:.03em}
.china-title{text-align:center;margin:4px 0 2px;font-size:30px;color:#522813}
.china-sub{text-align:center;color:#806a54;font-size:12px;margin-bottom:14px}
.china-meta{display:grid;grid-template-columns:repeat(4,1fr);gap:7px;border-top:1px solid #d7c5a5;border-bottom:1px solid #d7c5a5;padding:10px 0}
.china-meta div{padding:6px 8px;border-right:1px solid #eadfc7}
.china-meta div:nth-child(4n){border-right:0}
.china-meta span{display:block;font-size:10px;color:#8a745e}
.china-meta strong{display:block;margin-top:2px}
.china-section-title{margin:16px 0 8px;color:#6f321e;font-size:15px}
.china-panchang{display:grid;grid-template-columns:repeat(5,1fr);gap:7px}
.china-panchang div{background:#fff;border:1px solid #eadfc7;border-radius:10px;padding:9px}
.china-panchang span{display:block;font-size:10px;color:#8a745e}
.kundali-pair{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:8px}
.kundali-panel{background:#fff;border:1px solid #dec9a8;border-radius:14px;padding:12px}
.kundali-panel h4{text-align:center;margin:0 0 8px;color:#6f321e}
.kundali-svg{width:100%;height:auto;display:block;max-width:430px;margin:auto}
.kundali-svg .line{stroke:#9a5a38;stroke-width:1.8;fill:none}
.kundali-svg .sign{font-size:13px;font-weight:900;fill:#7b3f25}
.kundali-svg .planet{font-size:11px;fill:#2e241b}
.china-note{margin-top:12px;background:#fff5dc;border:1px solid #ead39b;border-radius:11px;padding:10px;font-size:12px;line-height:1.55}
.dasha-box{background:#fff;border:1px solid #dfceb1;border-radius:12px;padding:11px;margin-top:9px}
.astro-disclaimer{margin-top:12px;font-size:11px;color:#776c60;line-height:1.55}
@media(max-width:800px){.astro-form-grid{grid-template-columns:1fr}.astro-form-grid .full,.astro-advanced{grid-column:1}.astro-advanced-grid{grid-template-columns:1fr}.china-meta{grid-template-columns:1fr 1fr}.china-meta div:nth-child(4n){border-right:1px solid #eadfc7}.china-meta div:nth-child(2n){border-right:0}.china-panchang{grid-template-columns:1fr 1fr}.kundali-pair{grid-template-columns:1fr}}
@media(max-width:560px){.day{min-height:82px}.china-sheet{padding:13px}.china-title{font-size:25px}.china-meta{grid-template-columns:1fr}.china-meta div{border-right:0}.china-panchang{grid-template-columns:1fr 1fr}}

.china-sheet .planet-table{display:block;overflow-x:auto;white-space:nowrap}
@media(max-width:700px){.nav{height:auto;min-height:62px;padding:8px 0;align-items:flex-start;flex-direction:column}.tabs{width:100%;flex-wrap:nowrap;overflow-x:auto;padding-bottom:2px}.tabs button{white-space:nowrap}.hero{border-radius:20px}.grid{gap:12px}.card{border-radius:16px;padding:14px}}

/* v1.1.2: compact home + restored daily tools */
.hero{padding:14px 18px;border-radius:20px;grid-template-columns:minmax(280px,.82fr) minmax(0,1.8fr);gap:12px;align-items:center}
.hero h1{font-size:clamp(34px,4vw,52px);line-height:1.04;margin:2px 0 4px}
.hero>div:first-child{align-self:center}
.hero-side{grid-template-columns:repeat(4,minmax(0,1fr));gap:7px;align-items:stretch}
.glass{padding:9px 10px;border-radius:12px;min-height:84px}
.glass strong{font-size:15px;line-height:1.25;margin-top:2px}
.glass small{font-size:10px}
.hero select{padding:6px 8px;font-size:11px;margin-top:5px!important}
.today-badge{position:absolute;right:7px;bottom:7px;background:var(--g);color:#fff;border-radius:999px;padding:2px 6px;font-size:8px;font-weight:900;letter-spacing:.02em}
.day.today{box-shadow:inset 0 0 0 1px rgba(23,111,59,.12)}
.auth-card{display:block!important;padding:15px}
.auth-card h3{margin-bottom:4px}
.auth-intro{margin:0 0 10px;line-height:1.5}
.auth-form{gap:7px}
.auth-form input{padding:8px 9px}
.auth-form .go{padding:8px 10px}
.auth-status{margin:8px 0 4px}
.auth-buttons{margin-top:8px}
.note-box textarea{min-height:76px}
.detail.today-detail{border-color:#b8dcc3;background:linear-gradient(180deg,#fff,#fbfefc)}
@media(max-width:1000px){.hero{grid-template-columns:1fr}.hero-side{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:560px){.hero{padding:13px 14px}.hero-side{grid-template-columns:1fr 1fr}.glass{min-height:76px;padding:8px}}

/* v1.2 advanced Jyotish */
.kundali-trio{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin-top:10px}
.astro-section{margin-top:16px;padding-top:14px;border-top:1px solid #dbcdb7}
.astro-section>h3{margin:0 0 9px;color:#6f321e;font-size:16px}
.astro-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px}
.astro-grid .a-card{background:#fff;border:1px solid #e4d5bd;border-radius:11px;padding:9px;min-width:0}
.a-card span{display:block;font-size:10px;color:#8a745e}.a-card b{display:block;margin-top:3px;line-height:1.35}
.graha-state{display:flex;gap:4px;flex-wrap:wrap}.state-chip{display:inline-block;border-radius:999px;padding:3px 6px;font-size:9px;font-weight:800;background:#f2eee7;color:#665647}
.state-chip.good{background:#e8f5ec;color:#176f3b}.state-chip.warn{background:#fff0e8;color:#9b4c17}.state-chip.info{background:#edf2fb;color:#3f5684}
.house-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:7px}.house-card{background:#fff;border:1px solid #e5d7c1;border-radius:11px;padding:9px;font-size:11px;line-height:1.45}.house-card strong{color:#6f321e}.house-card small{display:block;color:#806f5e;margin-top:3px}
.yoga-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.yoga-card{background:#fff8e8;border:1px solid #ead39b;border-radius:11px;padding:10px}.yoga-card b{display:block;color:#6f321e;margin-bottom:4px}.yoga-card p{margin:0;font-size:11px;line-height:1.45;color:#685846}
.dasha-current{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.dasha-current>div{background:#fff;border:1px solid #dfceb1;border-radius:11px;padding:10px}.dasha-current span{display:block;font-size:10px;color:#8a745e}.dasha-current b{display:block;margin-top:3px;color:#6f321e}
.dasha-timeline{display:grid;gap:6px;margin-top:9px}.dasha-row{display:grid;grid-template-columns:120px 1fr 1fr;gap:8px;background:#fff;border:1px solid #eee1cc;border-radius:9px;padding:8px;font-size:11px}.dasha-row b{color:#6f321e}
.gochar-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px}.gochar-card{background:#f9fbf8;border:1px solid #dce8df;border-radius:11px;padding:10px}.gochar-card span{display:block;font-size:10px;color:#68756c}.gochar-card b{display:block;margin-top:3px}
.astro-two{display:grid;grid-template-columns:1fr 1fr;gap:10px}.astro-mini{background:#fff;border:1px solid #e3d6c2;border-radius:12px;padding:11px;line-height:1.55}.astro-mini h4{margin:0 0 6px;color:#6f321e}
.astro-method{margin-top:14px;border:1px dashed #cdbd9f;border-radius:11px;padding:10px;background:#fffdf8;font-size:11px;line-height:1.55;color:#6f6255}
@media(max-width:1000px){.kundali-trio{grid-template-columns:1fr 1fr}.astro-grid,.house-grid,.gochar-grid{grid-template-columns:repeat(2,1fr)}}
@media(max-width:700px){.kundali-trio,.astro-two,.yoga-grid{grid-template-columns:1fr}.dasha-current{grid-template-columns:1fr}.dasha-row{grid-template-columns:1fr}.astro-grid,.house-grid,.gochar-grid{grid-template-columns:1fr 1fr}}
@media(max-width:460px){.astro-grid,.house-grid,.gochar-grid{grid-template-columns:1fr}}

/* v1.3 Daily Life workspace */
.life-preview-card{border-color:#d7e8dc;background:linear-gradient(180deg,#fff,#fbfefc)}
.life-preview-list{display:grid;gap:6px;margin:8px 0 10px}
.life-mini{display:grid;grid-template-columns:1fr auto;gap:8px;align-items:center;padding:7px 8px;border-radius:9px;background:#f6f9f7;font-size:11px}
.life-mini b{font-size:11px}.life-mini span{color:#6a766e;font-size:10px;white-space:nowrap}
.life-hero{margin:18px 0 14px;border-radius:20px;padding:20px;background:linear-gradient(135deg,#176f3b,#245f3e);color:#fff;display:grid;grid-template-columns:1fr auto;gap:16px;align-items:center}
