async function loadOtdDate(md){
  const m=String(md||'').match(/^(\d{2})-(\d{2})$/);
  if(!m){timeline.innerHTML='<div class="notice">MM-DD format प्रयोग गर्नुहोस्।</div>';return}
  otdDate.value=md;
  timeline.innerHTML='<div class="notice">इतिहासका घटना —</div>';
  try{
    const j=await api('/api/on-this-day?month='+(+m[1])+'&day='+(+m[2]));
    OTD_ROWS=j.events||[];OTD_FILTER='all';
    const s=j.stats||{};
    otdStats.innerHTML='<div><span>कुल</span><strong>'+nd(s.total||0)+'</strong></div>'+
      '<div><span>घटना</span><strong>'+nd(s.events||0)+'</strong></div>'+
      '<div><span>जन्म</span><strong>'+nd(s.births||0)+'</strong></div>'+
      '<div><span>निधन</span><strong>'+nd(s.deaths||0)+'</strong></div>'+
      '<div><span>स्रोत-सहित</span><strong>'+nd(s.source_backed||0)+'</strong></div>';
    const cats=[...new Set(OTD_ROWS.map(x=>x.category).filter(Boolean))].sort();
    otdCategory.innerHTML='<option value="all">सबै category</option>'+cats.map(x=>'<option>'+esc(x)+'</option>').join('');
    otdTypes.querySelectorAll('button').forEach(btn=>{
      btn.classList.toggle('active',btn.dataset.type==='all');
      btn.onclick=()=>{OTD_FILTER=btn.dataset.type;otdTypes.querySelectorAll('button').forEach(x=>x.classList.toggle('active',x===btn));renderOtd()}
    });
    otdCategory.onchange=renderOtd;
    otdPrev.onclick=()=>loadOtdDate(shiftMD(md,-1));
    otdNext.onclick=()=>loadOtdDate(shiftMD(md,1));
    renderOtd()
  }catch(e){timeline.innerHTML='<div class="notice">'+esc(e.message||'Historical data could not load.')+'</div>'}
}

