function astroInterpret(j){
  const moon=j.moon||{},nak=moon.nakshatra||{},asc=j.ascendant?.rashi;
  const lead=asc
    ?'लग्नले बाहिरी जीवनमार्ग, चन्द्रले मानसिक प्रतिक्रिया र जन्मनक्षत्रले सूक्ष्म स्वभावको परम्परागत संकेत दिन्छ। यी तीनलाई ग्रहबल, भाव र दशासँग संयुक्त रूपमा पढिएको छ।'
    :'जन्मसमय अज्ञात भएकाले लग्न र भावफल रोकिएको छ। तलको व्याख्या चन्द्रराशि, नक्षत्र र दिन-आधारित ग्रहस्थितिमा सीमित छ।';
  const anchor='<div class="phalit-grid">'+
    (asc?'<div class="phalit-card"><h4>लग्न · '+esc(asc.ne)+'</h4><p>व्यक्तित्व र जीवनदिशाको आधार। लग्नेश र लग्नमा पर्ने ग्रह/दृष्टिले यसको अभिव्यक्ति बदल्छ; यसलाई एक्लै निश्चित फल मानिँदैन।</p></div>':'')+
    '<div class="phalit-card"><h4>जन्मराशि · '+esc(moon.rashi?.ne||'—')+'</h4><p>मन, स्मृति र दैनिक प्रतिक्रियाको चन्द्र-आधारित संकेत। गोचर र दशाको अनुभव बुझ्न यो मुख्य सन्दर्भ हो।</p></div>'+
    '<div class="phalit-card"><h4>नक्षत्र · '+esc(nak.name||'—')+'</h4><p>'+esc(NAK_TRAIT_NE[nak.name]||'परम्परागत मनोवृत्ति र कर्मप्रेरणाको सूक्ष्म संकेत')+'। पाद '+nd(nak.pada||'—')+' ले अभिव्यक्तिको ढाँचा थप सूक्ष्म बनाउँछ।</p></div>'+
    '<div class="phalit-card"><h4>दशा र गोचर कसरी पढ्ने?</h4><p>दशाले सक्रिय समय-विषय देखाउँछ; गोचरले वर्तमान वातावरण। जन्मकुण्डलीको मूल प्रतिज्ञा नहेरी कुनै एक गोचरबाट घटना निश्चित गरिँदैन।</p></div></div>';
  const graha=(j.planets||[]).map(p=>{
    const bh=p.house?BHAVA_MEAN_NE[p.house-1]:'जन्मसमय बिना भाव निर्धारण गरिएको छैन';
    const state=p.dignity?.ne&&p.dignity.code!=='ordinary'?' '+p.dignity.ne+' अवस्थाले फलको गुण बदल्न सक्छ।':'';
    const motion=p.motion?.retrograde?' वक्री भएकाले विषय आन्तरिक, पुनरावलोकनमुखी वा ढिलो अनुभव हुन सक्छ।':'';
    const vg=p.vargottama?' वर्गोत्तम संकेतले राशि-विषयमा तुलनात्मक स्थिरता देखाउँछ।':'';
    return '<div><b>'+esc(p.symbol)+' '+esc(p.ne)+'</b> · '+esc(p.rashi?.ne||'—')+(p.house?' · भाव '+nd(p.house):'')+'<br>'+esc(GRAHA_ROLE_NE[p.ne]||'परम्परागत ग्रहकारक')+'; '+esc(bh)+'।'+esc(state+motion+vg)+'</div>'
  }).join('');
  return '<div class="astro-section phalit-section"><h3>फलित व्याख्या · गणनाबाट व्याख्यासम्म</h3><div class="phalit-lead">'+lead+'</div>'+anchor+'<h4 style="margin:16px 0 8px">ग्रह–भाव अर्थ</h4><div class="graha-explain">'+graha+'</div><div class="astro-method">यो व्याख्या पारदर्शी नियममा आधारित सांस्कृतिक ज्योतिषीय पाठ हो। निश्चित भविष्यवाणी, चिकित्सा, कानुनी वा आर्थिक सल्लाह होइन। जन्मसमयको शुद्धता र reference-software cross-check ले time-sensitive भागको विश्वसनीयता बदल्छ।</div></div>'
}

