import { createClient } from "npm:@supabase/supabase-js@2";
export const FOUNDATION_JS="
(()=>{
  const NE=['०','१','२','३','४','५','६','७','८','९'];
  const toNeDigits=v=>String(v).replace(/[0-9]/g,d=>NE[+d]);
  const fromNeDigits=s=>String(s).replace(/[०-९]/g,d=>String(NE.indexOf(d)));
  const readLocal=(key,fallback)=>{try{const raw=localStorage.getItem(key);return raw?JSON.parse(raw):fallback}catch{return fallback}};
  const writeLocal=(key,value)=>{try{localStorage.setItem(key,JSON.stringify(value));return true}catch{return false}};
  const mergeRecords=(local,remote)=>{
    const byId=new Map();
    for(const r of [...(remote||[]),...(local||[])]){if(!r||!r.id)continue;const p=byId.get(r.id);if(!p){byId.set(r.id,r);continue}
      const rt=Date.parse(r.updatedAt||0),pt=Date.parse(p.updatedAt||0),newer=rt>=pt?r:p,older=newer===r?p:r;byId.set(r.id,{...older,...newer});
    }
    return [...byId.values()];
  };
  const relativeTimeNe=(date,now=new Date())=>{const s=Math.max(0,Math.round((now-new Date(date))/1000));if(s<60)return'भर्खरै';const m=Math.floor(s/60);if(m<60)return toNeDigits(m)+' मिनेट अघि';const h=Math.floor(m/60);if(h<24)return toNeDigits(h)+' घण्टा अघि';const d=Math.floor(h/24);return d<30?toNeDigits(d)+' दिन अघि':''};
  const countdownNe=days=>days===0?'आज':days===1?'भोलि':toNeDigits(days)+' दिन बाँकी';
  let flags=null;
  async function loadFlags(){if(flags)return flags;try{const r=await fetch('/api/flags',{cache:'no-store'}),j=await r.json();flags=j.flags||{}}catch{flags={}}return flags}
  async function flag(key){return !!(await loadFlags())[key]}
  window.NM={toNeDigits,fromNeDigits,readLocal,writeLocal,mergeRecords,relativeTimeNe,countdownNe,flag,loadFlags};
})();
";
