function setTz(v){if(!valid(v)){q('#tzStatus').textContent='Timezone मान्य छैन। उदाहरण: America/Chicago';return}tz=v;localStorage.setItem(KEY,tz);q('#customTz').value=tz;q('#tzStatus').textContent='';draw()}
