export function polishLegacyHtml(html,path){
  var meta=routeMeta(path),robots=privatePath(path)?"noindex,nofollow":"index,follow",canonical=BASE+(path==="/"?"":path);
  var h=html.replaceAll("नेपाल मिति","मेरो पात्रो").replaceAll("Nepal Miti","Mero Patro").replaceAll("NEPAL MITI","MERO PATRO").replaceAll("Nepali Patro","Mero Patro").replace(/<title>[\s\S]*?<\/title>/i,'<title>'+esc(meta.title)+' · मेरो पात्रो</title>').replace(/<meta\s+name=["']robots["'][^>]*>/i,'<meta name="robots" content="'+robots+'">').replace(/<meta\s+name=["']theme-color["'][^>]*>/i,'<meta name="theme-color" content="#176F3B">').replace(/Developed by Suraj Dahal\s*·\s*Contact:\s*<a[^>]*>[^<]*<\/a>/gi,"").replace(/✦AI/g,"");
  if(!/name=["']robots["']/i.test(h))h=h.replace("</head>",'<meta name="robots" content="'+robots+'"></head>');
  if(!/name=["']description["']/i.test(h))h=h.replace("</head>",'<meta name="description" content="'+esc(meta.description)+'"></head>');
  if(!/rel=["']canonical["']/i.test(h))h=h.replace("</head>",'<link rel="canonical" href="'+canonical+'"></head>');
  if(!/property=["']og:site_name["']/i.test(h))h=h.replace("</head>",'<meta property="og:site_name" content="मेरो पात्रो"><meta property="og:title" content="'+esc(meta.title)+' · मेरो पात्रो"><meta property="og:description" content="'+esc(meta.description)+'"><meta property="og:url" content="'+canonical+'"><meta name="twitter:card" content="summary_large_image"></head>');
  if(h.indexOf("lp-accessibility-patch")<0)h=h.replace("</head>",'<style id="lp-accessibility-patch">:focus-visible{outline:2px solid #176F3B!important;outline-offset:2px!important}@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important;scroll-behavior:auto!important}}.lp-legacy-skip{position:fixed;left:10px;top:8px;z-index:99999;transform:translateY(-160%);background:#0F5A2E;color:#fff;padding:7px 10px;border-radius:8px}.lp-legacy-skip:focus{transform:none}</style></head>');
  if(h.indexOf("lp-legacy-skip")<0)h=h.replace(/<body([^>]*)>/i,'<body$1><a class="lp-legacy-skip" href="#main-content">मुख्य सामग्रीमा जानुहोस्</a>');
  if(!/id=["']main-content["']/.test(h))h=h.replace(/<main(\s|>)/i,'<main id="main-content"$1');
  h=h.replace('<span class="mark">प</span> मेरो पात्रो','<span class="mark">म</span> मेरो पात्रो');
  if(h.indexOf('href="/about"')<0&&h.indexOf("</body>")>=0)h=h.replace("</body>",'<div style="max-width:1100px;margin:28px auto;padding:18px 20px;border-top:1px solid #dfe7e1;font:13px/1.6 system-ui;color:#68756c"><a href="/about">हाम्रो बारेमा</a> · <a href="/sources">स्रोत र शुद्धता</a> · <a href="/privacy">गोपनीयता</a> · <a href="/terms">सर्तहरू</a> · <a href="/contact">सम्पर्क</a><br>© २०२६ मेरो पात्रो · सर्वाधिकार सुरक्षित</div></body>');
  return h;
}

